from functools import wraps

def cached(func):
    _cache = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in _cache:
            _cache[key] = func(*args, **kwargs)
        return _cache[key]
    return wrapper
```
Usage: `@cached` above any pure function. Results are stored in `_cache` dict keyed by arguments.

